import { describe, it, expect, beforeEach, vi } from 'vitest';
import { TodoStore } from './todoStore';

// jsdom isn't configured, so stub the storage the store reaches for.
vi.mock('../utils/storage', () => ({
  loadTasks: () => [],
  saveTasks: vi.fn(),
  loadFilter: () => 'all',
  saveFilter: vi.fn()
}));

describe('TodoStore.add', () => {
  let store: TodoStore;
  let seen: number;

  beforeEach(() => {
    store = new TodoStore();
    seen = 0;
    store.on(() => {
      seen += 1;
    });
  });

  it('rejects an empty label', () => {
    store.add('');
    expect(store.getVisibleTasks()).toHaveLength(0);
  });

  it('rejects a whitespace-only label', () => {
    store.add('   ');
    expect(store.getVisibleTasks()).toHaveLength(0);
  });

  it('rejects tabs and newlines', () => {
    store.add('\t\n');
    expect(store.getVisibleTasks()).toHaveLength(0);
  });

  it('does not notify listeners when an add is rejected', () => {
    store.add('   ');
    expect(seen).toBe(0);
  });

  it('trims surrounding whitespace but still adds', () => {
    store.add('  buy milk  ');
    expect(store.getVisibleTasks()).toHaveLength(1);
    expect(store.getVisibleTasks()[0].label).toBe('buy milk');
  });

  it('adds an ordinary label unchanged', () => {
    store.add('buy milk');
    expect(store.getVisibleTasks()[0].label).toBe('buy milk');
  });
});

